/**
 * @event
 * @name scwin.ipt_editYn_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_editYn_onclick = function(e){
    try {
        const ev = e;
